// Integration (Phase 7 P3.4, migration 0020): automatic student / trainer codes on the local
// 0001–0020 database, plus a separate upgrade database (0001–0019 with legacy codes) to prove the
// preflight, the sequence start and that existing codes are never changed.
//   STU-00001… / TRN-00001… — generated by the database at invitation creation and by
//   admin_set_user_role; copied (unchanged) by accept_user_invitation; never supplied by callers;
//   race-safe (sequences); unique case-insensitively; immutable once a record exists.
import { after, before, test } from "node:test";
import assert from "node:assert/strict";
import fs from "node:fs";
import path from "node:path";
import { randomUUID } from "node:crypto";
import { fileURLToPath } from "node:url";
import { PgDatabase } from "./pg-client.mjs";
import { bindInvitation, db } from "./harness.mjs";

const here = path.dirname(fileURLToPath(import.meta.url));
const MIGRATIONS = path.resolve(here, "../../supabase/migrations");
const UPGRADE_DB = "qi_codes_upgrade";

let W;
const as = (id) => db.client({ role: "authenticated", userId: id });
async function call(client, fn, args = {}) {
  const { data, error } = await client.rpc(fn, args);
  if (error) throw new Error(`${fn}: ${error.code} ${error.message}`);
  return data;
}
async function err(client, fn, args = {}) {
  const { error } = await client.rpc(fn, args);
  return error;
}
let n = 0;
const uniq = (p) => `${p}${Date.now().toString(36)}${++n}`;
const student = (o = {}) => ({ email: `${uniq("uc")}@codes.test`, role: "student", full_name: "Code Student", ...o });
const trainer = (o = {}) => ({ email: `${uniq("uc")}@codes.test`, role: "trainer", full_name: "Code Trainer", ...o });
const num = (code) => Number(code.slice(4));
const STU = /^STU-\d{5,}$/;
const TRN = /^TRN-\d{5,}$/;
/** SQL as an authenticated user, the way PostgREST runs a direct table write (RLS applies). */
const asUserSql = (userId, sql) =>
  db.run(`begin;\nset local role authenticated;\nselect set_config('request.jwt.claims', '${JSON.stringify({ sub: userId })}', true);\n${sql};\ncommit;`);
const sqlState = (stderr) => /ERROR:\s+([0-9A-Z]{5}):/.exec(stderr)?.[1] ?? null;

before(async () => {
  await db.exec(`
    insert into t.ids (k, v) select 'uc_' || k, gen_random_uuid() from unnest(array['SA','ADOPT','S1']) k;
    insert into auth.users (id, email) select v, lower(k) || '@codes.test' from t.ids where k in ('uc_SA','uc_ADOPT','uc_S1');
    update public.profiles set role = 'super_admin' where id = t.id('uc_SA');
    update public.profiles set account_status = 'active' where id in (t.id('uc_SA'), t.id('uc_ADOPT'), t.id('uc_S1'));
    insert into public.students (id, student_code, full_name) values (t.id('uc_S1'), 'UC-S1', 'Legacy Coded Student');`);
  W = await db.admin("select json_object_agg(k, v) from t.ids");
});

after(async () => {
  await db.run(`drop database if exists ${UPGRADE_DB} with (force);`);
});

test("1–2, 12. invitations get generated codes: STU for students, TRN for trainers, none for Super Admins; prefixes never cross", async () => {
  const sa = as(W.uc_SA);
  const s1 = await call(sa, "create_user_invitation", { p: student() });
  const t1 = await call(sa, "create_user_invitation", { p: trainer() });
  const s2 = await call(sa, "create_user_invitation", { p: student() });
  const a1 = await call(sa, "create_user_invitation", { p: { email: `${uniq("uc")}@codes.test`, role: "super_admin", full_name: "Code Admin" } });
  assert.match(s1.code, STU);
  assert.match(t1.code, TRN);
  assert.match(s2.code, STU);
  assert.equal("code" in a1, false);
  assert.ok(num(s2.code) > num(s1.code), "student numbers increase");
  assert.equal(num(s2.code), num(s1.code) + 1, "a trainer invitation does not consume a student number");
  const rows = await db.admin(`select json_agg(json_build_object('s', student_code, 't', trainer_code) order by created_at)
    from public.user_invitations where id in ('${s1.invitation_id}', '${t1.invitation_id}', '${a1.invitation_id}')`);
  assert.deepEqual(rows, [{ s: s1.code, t: null }, { s: null, t: t1.code }, { s: null, t: null }]);
});

test("3, 11. callers cannot supply a code: rejected by the functions; direct Super Admin writes cannot insert or change one", async () => {
  const sa = as(W.uc_SA);
  for (const p of [student({ student_code: "STU-99999" }), trainer({ trainer_code: "TRN-99999" }), student({ trainer_code: "X" })]) {
    assert.equal((await err(sa, "create_user_invitation", { p }))?.code, "22023", JSON.stringify(p));
  }
  assert.equal((await err(sa, "admin_set_user_role", { p_user_id: W.uc_ADOPT, p_role: "student", p_details: { student_code: "STU-99999", full_name: "X" } }))?.code, "22023");
  // Direct writes through the Super Admin's own session (the 0003 RLS write policy still allows other columns).
  let r = await asUserSql(W.uc_SA, `insert into public.students (id, student_code, full_name) values ('${W.uc_ADOPT}', 'STU-99999', 'Injected')`);
  assert.equal(sqlState(r.stderr), "42501", r.stderr);
  r = await asUserSql(W.uc_SA, `insert into public.students (id, full_name) values ('${W.uc_ADOPT}', 'Injected')`);
  assert.equal(sqlState(r.stderr), "42501", "no direct insert even without a code");
  r = await asUserSql(W.uc_SA, `update public.students set student_code = 'STU-99999' where id = '${W.uc_S1}'`);
  assert.equal(sqlState(r.stderr), "42501", r.stderr);
  r = await asUserSql(W.uc_SA, `update public.students set full_name = 'Renamed By Admin' where id = '${W.uc_S1}'`);
  assert.equal(r.code, 0, "other columns stay editable under the existing RLS policy");
  assert.deepEqual(await db.admin(`select json_build_object('code', student_code, 'name', full_name) from public.students where id = '${W.uc_S1}'`), { code: "UC-S1", name: "Renamed By Admin" });
  assert.equal(await db.admin(`select count(*) from public.students where id = '${W.uc_ADOPT}'`), 0);
  // No client access to the generator or the sequences.
  assert.deepEqual(await db.admin(`select json_build_object(
      'gen', has_function_privilege('authenticated', 'public.user_mgmt_next_code(text)', 'EXECUTE'),
      'anon_gen', has_function_privilege('anon', 'public.user_mgmt_next_code(text)', 'EXECUTE'),
      'seq', has_sequence_privilege('authenticated', 'public.student_code_seq', 'USAGE') or has_sequence_privilege('authenticated', 'public.trainer_code_seq', 'USAGE'))`),
    { gen: false, anon_gen: false, seq: false });
});

test("4. concurrent generations never share a code (parallel requests and a held transaction)", async () => {
  const sa = as(W.uc_SA);
  const results = await Promise.all(Array.from({ length: 8 }, () => call(sa, "create_user_invitation", { p: student() })));
  const codes = results.map((r) => r.code);
  assert.equal(new Set(codes).size, codes.length, codes.join(","));
  for (const c of codes) assert.match(c, STU);
  // A generation inside a transaction that is still open does not block or duplicate another one.
  const claims = JSON.stringify({ sub: W.uc_SA });
  const held = db.run(`begin;\nset local role authenticated;\nselect set_config('request.jwt.claims', '${claims}', true);\nselect public.create_user_invitation('${JSON.stringify(student())}'::jsonb);\nselect pg_sleep(1.5);\ncommit;`);
  await new Promise((resolve) => setTimeout(resolve, 300));
  const other = await call(sa, "create_user_invitation", { p: student() });
  assert.match(other.code, STU, "not blocked by the open transaction");
  assert.equal((await held).code, 0);
  const all = await db.admin(`select json_agg(student_code) from public.user_invitations where student_code like 'STU-%'`);
  assert.equal(new Set(all).size, all.length, "no duplicate code across all invitations");
});

test("6. codes are immutable once a record exists — for every writer, including the superuser", async () => {
  const r = await db.run(`update public.students set student_code = 'CHANGED' where id = '${W.uc_S1}';`);
  assert.notEqual(r.code, 0);
  assert.match(r.stderr, /cannot be changed/);
  const t = await db.run(`update public.trainers set trainer_code = 'CHANGED' where id = (select v from t.ids where k = 'T1');`);
  assert.notEqual(t.code, 0);
  assert.equal(await db.admin(`select student_code from public.students where id = '${W.uc_S1}'`), "UC-S1");
  assert.equal(await db.admin(`select trainer_code from public.trainers where id = (select v from t.ids where k = 'T1')`), "T1");
});

test("7. case-insensitive uniqueness: no record may differ from another only by case; the generator skips taken codes of either kind", async () => {
  const twin = randomUUID();
  await db.exec(`insert into auth.users (id, email) values ('${twin}', '${uniq("ci")}@codes.test');`);
  const r = await db.run(`insert into public.students (id, student_code, full_name) values ('${twin}', 'uc-s1', 'Case Twin');`);
  assert.notEqual(r.code, 0);
  assert.match(r.stderr, /students_student_code_ci_key|duplicate key/);
  // A privileged write takes the next student number as a TRAINER code (cross-kind) and the one after in lower case: both skipped.
  const next = Number(await db.admin(`select last_value + 1 from public.student_code_seq`));
  const pad = (k) => `STU-${String(k).padStart(5, "0")}`;
  const crossId = randomUUID();
  const lowerId = randomUUID();
  await db.exec(`
    insert into auth.users (id, email) values ('${crossId}', '${uniq("x")}@codes.test'), ('${lowerId}', '${uniq("x")}@codes.test');
    update public.profiles set role = 'trainer' where id = '${crossId}';
    insert into public.trainers (id, trainer_code, full_name) values ('${crossId}', '${pad(next)}', 'Cross Kind');
    insert into public.students (id, student_code, full_name) values ('${lowerId}', '${pad(next + 1).toLowerCase()}', 'Lower Case');`);
  const got = await call(as(W.uc_SA), "create_user_invitation", { p: student() });
  assert.equal(got.code, pad(next + 2), "both taken codes skipped; numbers are never reused");
});

test("8. revoked and expired invitations keep their numbers; nothing is reused", async () => {
  const sa = as(W.uc_SA);
  const a = await call(sa, "create_user_invitation", { p: student() });
  await call(sa, "revoke_user_invitation", { p_invitation_id: a.invitation_id });
  const b = await call(sa, "create_user_invitation", { p: student() });
  await db.exec(`update public.user_invitations set expires_at = created_at + interval '1 millisecond' where id = '${b.invitation_id}';`);
  await call(sa, "expire_user_invitations");
  const c = await call(sa, "create_user_invitation", { p: student() });
  assert.ok(num(b.code) > num(a.code) && num(c.code) > num(b.code));
  assert.deepEqual(await db.admin(`select json_agg(student_code order by created_at) from public.user_invitations where id in ('${a.invitation_id}', '${b.invitation_id}')`), [a.code, b.code], "revoked/expired rows keep their codes");
});

test("9–10. acceptance copies the invitation's code; admin_set_user_role generates one for a record it creates", async () => {
  const sa = as(W.uc_SA);
  const email = `${uniq("acc")}@codes.test`;
  const inv = await call(sa, "create_user_invitation", { p: student({ email }) });
  const uid = randomUUID();
  await db.exec(`insert into auth.users (id, email) values ('${uid}', '${email}');`);
  await bindInvitation(inv.invitation_id, uid); // 0029a: only the bound account accepts
  assert.equal((await call(as(uid), "accept_user_invitation")).ok, true);
  assert.equal(await db.admin(`select student_code from public.students where id = '${uid}'`), inv.code);

  const r = await call(sa, "admin_set_user_role", { p_user_id: W.uc_ADOPT, p_role: "trainer", p_details: { full_name: "Adopted Trainer" } });
  assert.equal(r.ok, true);
  assert.match(r.code, TRN);
  assert.equal(await db.admin(`select trainer_code from public.trainers where id = '${W.uc_ADOPT}'`), r.code);
  assert.deepEqual(await call(sa, "admin_set_user_role", { p_user_id: W.uc_ADOPT, p_role: "trainer" }), { ok: false, reason: "unchanged" }, "no second record or code");
});

test("5 + preflight: 0020 on a 0019 database refuses case-insensitive duplicates, keeps every existing code, and starts above existing numbers", async () => {
  const up = new PgDatabase({ psql: process.env.QI_PSQL, port: Number(process.env.QI_PORT), database: UPGRADE_DB });
  let r = await db.run(`drop database if exists ${UPGRADE_DB} with (force);\ncreate database ${UPGRADE_DB};`);
  assert.equal(r.code, 0, r.stderr);
  const read = (f) => fs.readFileSync(f, "utf8").replace(/\r\n/g, "\n");
  for (const f of [path.join(here, "fixtures/bootstrap.sql"), ...fs.readdirSync(MIGRATIONS).filter((x) => /^00(0\d|1\d)_.*\.sql$/.test(x)).sort().map((x) => path.join(MIGRATIONS, x)), path.join(here, "fixtures/seed.sql")]) {
    r = await up.run(read(f));
    assert.equal(r.code, 0, `${path.basename(f)}: ${r.stderr}`);
  }
  // Legacy data: free-form codes, already-formatted codes (one lower case), a case-insensitive duplicate,
  // and a revoked invitation that used a high STU number.
  await up.exec(`
    insert into t.ids (k, v) select 'lg_' || k, gen_random_uuid() from unnest(array['S7','T12','FREE','DUP1','DUP2','T9']) k;
    insert into auth.users (id) select v from t.ids where k like 'lg\\_%';
    update public.profiles set role = 'trainer' where id in (t.id('lg_T12'), t.id('lg_T9'));
    insert into public.students (id, student_code, full_name) values
      (t.id('lg_S7'), 'STU-00007', 'Legacy Seven'), (t.id('lg_FREE'), 'Free-Form 1', 'Legacy Free'),
      (t.id('lg_DUP1'), 'DUPE', 'Dup One'), (t.id('lg_DUP2'), 'dupe', 'Dup Two');
    insert into public.trainers (id, trainer_code, full_name) values (t.id('lg_T12'), 'trn-00012', 'Legacy Twelve'), (t.id('lg_T9'), 'TRN-9', 'Short Nine');
    insert into public.user_invitations (email, intended_role, full_name, student_code, invited_by, expires_at)
      values ('legacy.revoked@codes.test', 'student', 'Legacy Revoked', 'STU-00020', t.id('A'), now() + interval '1 day');
    update public.user_invitations set status = 'revoked', revoked_at = now() where email = 'legacy.revoked@codes.test';`);
  const M0020 = path.join(MIGRATIONS, "0020_automatic_user_codes.sql");
  r = await up.run(read(M0020));
  assert.notEqual(r.code, 0, "refused while codes collide case-insensitively");
  assert.match(r.stderr, /collide case-insensitively \(student dupe\)/);
  assert.equal(await up.admin("select to_regclass('public.student_code_seq') is null"), true, "nothing was created");

  // Resolved by the operator (not by the migration), then applied.
  await up.exec(`delete from public.students where id = t.id('lg_DUP2');`);
  const before = await up.admin(`select json_build_object(
      's', (select json_agg(student_code order by student_code) from public.students),
      't', (select json_agg(trainer_code order by trainer_code) from public.trainers),
      'i', (select json_agg(coalesce(student_code, trainer_code) order by created_at) from public.user_invitations))`);
  r = await up.run(read(M0020));
  assert.equal(r.code, 0, r.stderr);
  const afterCodes = await up.admin(`select json_build_object(
      's', (select json_agg(student_code order by student_code) from public.students),
      't', (select json_agg(trainer_code order by trainer_code) from public.trainers),
      'i', (select json_agg(coalesce(student_code, trainer_code) order by created_at) from public.user_invitations))`);
  assert.deepEqual(afterCodes, before, "no existing code changed or backfilled");

  // Sequences start above the highest existing number (records AND invitations of any status, case-insensitive).
  const P = await up.admin("select json_object_agg(k, v) from t.ids");
  const upA = up.client({ role: "authenticated", userId: P.A });
  const s = (await upA.rpc("create_user_invitation", { p: { email: "new.s@codes.test", role: "student", full_name: "New S" } })).data;
  const t = (await upA.rpc("create_user_invitation", { p: { email: "new.t@codes.test", role: "trainer", full_name: "New T" } })).data;
  assert.equal(s.code, "STU-00021", "above the revoked legacy invitation STU-00020");
  assert.equal(t.code, "TRN-00013", "above the lower-case legacy trn-00012");
  // Re-running is refused by the preflight.
  r = await up.run(read(M0020));
  assert.notEqual(r.code, 0);
  assert.match(r.stderr, /0020 already applied/);
});
